   198	@Service
   199	public class OrderService {
   200	
   201	
   202	    private static final Duration PAYMENT_DEADLINE = Duration.ofHours(48);
   203	
   204	    private final CheckoutCalculator calculator;
   205	    private final OrderRepository orders;
   206	    private final CustomerRepository customers;
   207	    private final InventoryService inventory;
