   212	    public OrderService(CheckoutCalculator calculator, OrderRepository orders, CustomerRepository customers,
   213	            InventoryService inventory, List<OrderLifecycleListener> listeners, TransactionTemplate transaction,
   214	            Clock clock) {
   215	        this.calculator = calculator;
   216	        this.orders = orders;
   217	        this.customers = customers;
   218	        this.inventory = inventory;
   219	        this.listeners = listeners;
   220	        this.transaction = transaction;
   221	        this.clock = clock;
   222	    }
