   224	    public Order place(CheckoutRequest request) {
   225	
   226	        CheckoutSummary summary = calculator.calculate(request);
   227	        Order order = new Order(
   228	                UUID.randomUUID().toString(),
   229	                request.cpf(),
   230	                request.email(),
   231	                OrderStatus.AWAITING_PAYMENT,
   232	                Instant.now(clock).truncatedTo(ChronoUnit.SECONDS),
   233	                summary,
   234	                request.items(),
   235	                null);
   236	        transaction.executeWithoutResult(status -> {
   237	            customers.createIfAbsent(order.cpf());
   238	            orders.insert(order);
   239	        });
   240	        return order;
   241	    }
