   243	    @Transactional(readOnly = true)
   244	    public Order get(String id) {
   245	        return orders.findById(id).orElseThrow(OrderService::notFound);
   246	    }
   247	
   248	    @Transactional(noRollbackFor = PaymentRejectedException.class)
   249	    public Order registerPayment(String id, String transactionId, String paidAtText) {
   250	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
   251	        Instant paidAt = parseInstant(paidAtText);
   252	        if (transactionId == null || paidAt == null) {
   253	            throw ApiException.unprocessable(ErrorCode.INVALID_ORDER);
   254	        }
   255	        var previousNotice = orders.findPaymentNotice(id, transactionId);
   256	        if (previousNotice.isPresent()) {
   257	            return repeat(order, previousNotice.get());
   258	        }
   259	        requireTransition(order, OrderStatus.PAID);
   260	
   261	        if (Duration.between(order.createdAt(), paidAt).compareTo(PAYMENT_DEADLINE) > 0) {
   262	            return reject(order, transactionId, PaymentNoticeOutcome.ORDER_EXPIRED);
   263	        }
   264	        if (!inventory.take(order.items())) {
   265	            return reject(order, transactionId, PaymentNoticeOutcome.INSUFFICIENT_STOCK);
   266	        }
   267	        orders.markPaid(id, transactionId, paidAt);
   268	        orders.savePaymentNotice(id, transactionId, PaymentNoticeOutcome.ACCEPTED);
   269	        Order paid = reload(id);
   270	        listeners.forEach(listener -> listener.paymentApproved(paid));
   271	        return paid;
   272	    }
