   274	    @Transactional
   275	    public Order ship(String id, String trackingCode) {
   276	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
   277	        if (trackingCode == null) {
   278	            throw ApiException.unprocessable(ErrorCode.INVALID_ORDER);
   279	        }
   280	        requireTransition(order, OrderStatus.SHIPPED);
   281	        orders.markShipped(id, trackingCode);
   282	        Order shipped = reload(id);
   283	        listeners.forEach(listener -> listener.shipped(shipped));
   284	        return shipped;
   285	    }
   286	
   287	    @Transactional
   288	    public Order deliver(String id) {
   289	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
   290	        requireTransition(order, OrderStatus.DELIVERED);
   291	        orders.updateStatus(id, OrderStatus.DELIVERED);
   292	        return reload(id);
   293	    }
   294	
   295	    @Transactional
   296	    public Order cancel(String id) {
   297	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
   298	        requireTransition(order, OrderStatus.CANCELLED);
   299	        return cancelLocked(order);
   300	    }
   301	
   302	    private Order repeat(Order order, PaymentNoticeOutcome outcome) {
   303	        return switch (outcome) {
   304	            case ACCEPTED -> order;
   305	            case ORDER_EXPIRED -> throw new PaymentRejectedException(ErrorCode.ORDER_EXPIRED);
   306	            case INSUFFICIENT_STOCK -> throw new PaymentRejectedException(ErrorCode.INSUFFICIENT_STOCK);
   307	        };
   308	    }
   309	
   310	    private Order reject(Order order, String transactionId, PaymentNoticeOutcome outcome) {
   311	        orders.savePaymentNotice(order.id(), transactionId, outcome);
   312	        cancelLocked(order);
   313	        return repeat(order, outcome);
   314	    }
   315	
   316	    private Order cancelLocked(Order order) {
   317	        orders.updateStatus(order.id(), OrderStatus.CANCELLED);
   318	        Order cancelled = reload(order.id());
   319	        listeners.forEach(listener -> listener.cancelled(cancelled, order.status()));
   320	        return cancelled;
   321	    }
   322	
   323	    private Order reload(String id) {
   324	        return orders.findById(id).orElseThrow(OrderService::notFound);
   325	    }
   326	
   327	    private static void requireTransition(Order order, OrderStatus next) {
   328	        if (!order.status().canMoveTo(next)) {
   329	            throw ApiException.conflict(ErrorCode.OPERATION_NOT_ALLOWED);
   330	        }
   331	    }
   332	
   333	    private static Instant parseInstant(String text) {
   334	        if (text == null) {
   335	            return null;
   336	        }
   337	        try {
   338	            return OffsetDateTime.parse(text).toInstant();
   339	        } catch (DateTimeParseException e) {
   340	            return null;
   341	        }
   342	    }
   343	
   344	    private static ApiException notFound() {
   345	        return ApiException.notFound(ErrorCode.ORDER_NOT_FOUND);
   346	    }
   347	}
